import{_ as e,o as d,c as o,a5 as a}from"./chunks/framework.CcrBcQWS.js";const m=JSON.parse('{"title":"Sport Client — Python Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/python/sport-client.md","filePath":"software/sdk/python/sport-client.md","lastUpdated":1787021357000}'),s={name:"software/sdk/python/sport-client.md"};function n(i,t,r,c,l,p){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="sport-client-—-python-example" tabindex="-1">Sport Client — Python Example <a class="header-anchor" href="#sport-client-—-python-example" aria-label="Permalink to &quot;Sport Client — Python Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/python/example/sport/rbq_sport_client.py</code></p><p>Python port of the C++ <a href="/RBQ/nightly/software/sdk/cpp/sport-client.html"><code>rbq_sport_client</code></a>.<br> An interactive terminal application that sends <strong>SportClient</strong> commands to the robot one at a time, looping at <strong>50 Hz</strong>.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The program has a single main loop that:</p><ol><li>Reads a line of input from <code>stdin</code> (<code>list</code>, a command name, or a command ID).</li><li>Updates the active <code>TestOption</code>.</li><li>Calls the matching <code>SportClient</code> method on every 20 ms tick.</li></ol><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><code>rbq_sdk_py</code> installed — see <a href="/RBQ/nightly/software/sdk/python/overview.html">Python SDK Overview</a>.</li><li>Robot stack running (simulation or hardware) and reachable on the chosen network interface.</li></ul><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>From <code>rbq_sdk/python/example/sport/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_sport_client.py</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networkInterfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># e.g.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_sport_client.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span></code></pre></div><h2 id="available-commands" tabindex="-1">Available commands <a class="header-anchor" href="#available-commands" aria-label="Permalink to &quot;Available commands&quot;">​</a></h2><p>Type <code>list</code> at the prompt to print all commands.</p><table tabindex="0"><thead><tr><th>ID</th><th>Name</th><th>SportClient method called</th></tr></thead><tbody><tr><td>0</td><td><code>damp</code></td><td><code>Damp()</code></td></tr><tr><td>1</td><td><code>balance_stand</code></td><td><code>BalanceStand()</code></td></tr><tr><td>2</td><td><code>stop_move</code></td><td><code>StopMove()</code></td></tr><tr><td>3</td><td><code>stand_down</code></td><td><code>StandDown()</code></td></tr><tr><td>4</td><td><code>recovery_stand</code></td><td><code>RecoveryStand()</code></td></tr><tr><td>5</td><td><code>move</code></td><td><code>Move(0.0, 0.0, 0.5)</code> — rotate in place</td></tr><tr><td>6</td><td><code>switch_gait</code></td><td><code>SwitchGait(0)</code></td></tr><tr><td>7</td><td><code>speed_level</code></td><td><code>SpeedLevel(1)</code></td></tr><tr><td>8</td><td><code>get_state</code></td><td><code>GetState()</code> — prints FSM ID, name, speed level, auto-recovery, process state</td></tr><tr><td>9</td><td><code>recovery_switch</code></td><td><code>SetAutoRecovery(0)</code></td></tr><tr><td>10</td><td><code>body_height</code></td><td><code>BodyHeight(0.3)</code></td></tr><tr><td>11</td><td><code>stand_up</code></td><td><code>StandUp()</code></td></tr><tr><td>12</td><td><code>enter_leftside_gait</code></td><td><code>LeftSideGait(1)</code></td></tr><tr><td>13</td><td><code>exit_leftside_gait</code></td><td><code>LeftSideGait(0)</code></td></tr><tr><td>14</td><td><code>enter_handstand</code></td><td><code>HandStand(1)</code></td></tr><tr><td>15</td><td><code>exit_handstand</code></td><td><code>HandStand(0)</code></td></tr><tr><td>16</td><td><code>front_flip</code></td><td><code>FrontFlip()</code> ⚠️</td></tr><tr><td>17</td><td><code>back_flip</code></td><td><code>BackFlip()</code> ⚠️</td></tr><tr><td>18</td><td><code>pose</code></td><td><code>BodyPosition(0.2, 0.2, -0.2, 0.2)</code></td></tr><tr><td>19</td><td><code>euler</code></td><td><code>Euler(0.2, 0.3, 0.3)</code></td></tr></tbody></table><blockquote><p><strong>⚠️ Caution</strong> — <code>front_flip</code> and <code>back_flip</code> require a clear open area.</p></blockquote><h2 id="usage-example" tabindex="-1">Usage example <a class="header-anchor" href="#usage-example" aria-label="Permalink to &quot;Usage example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ python3 rbq_sport_client.py eth0</span></span>
<span class="line"><span>Input &quot;list &quot; to list all test option ...</span></span>
<span class="line"><span>balance_stand</span></span>
<span class="line"><span>Test: balance_stand, test_id: 1</span></span>
<span class="line"><span>Request successed: balance_stand, code: 0</span></span>
<span class="line"><span>move</span></span>
<span class="line"><span>Test: move, test_id: 5</span></span>
<span class="line"><span>Request successed: move, code: 0</span></span></code></pre></div><h2 id="key-implementation-notes" tabindex="-1">Key implementation notes <a class="header-anchor" href="#key-implementation-notes" aria-label="Permalink to &quot;Key implementation notes&quot;">​</a></h2><ul><li><strong><code>SetTimeout(25.0)</code></strong>: The Python <code>SportClient</code> sets a 25-second timeout — relevant for RPC-style calls like <code>GetState</code>.</li><li><strong>50 Hz pacing</strong>: Uses <code>time.sleep(max(0.0, next_tick - time.monotonic()))</code> for accurate loop timing.</li><li><strong><code>get_state</code> response</strong>: Returns a <code>dict</code> with keys <code>fsm_id</code>, <code>fsm_name</code>, <code>speed_level</code>, <code>auto_recovery_switch</code>, <code>process_state</code>.</li></ul><h2 id="differences-from-the-c-version" tabindex="-1">Differences from the C++ version <a class="header-anchor" href="#differences-from-the-c-version" aria-label="Permalink to &quot;Differences from the C++ version&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>C++</th><th>Python</th></tr></thead><tbody><tr><td>Timeout</td><td>default</td><td><code>SetTimeout(25.0)</code> set explicitly</td></tr><tr><td><code>ConvertToInt</code> on failure</td><td>returns <code>-1</code></td><td>returns <code>None</code> (no false match on ID 0)</td></tr><tr><td>Terminal input</td><td><code>std::getline</code> blocking</td><td><code>input()</code> blocking</td></tr><tr><td>Error message</td><td>prints count</td><td>prints count</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/sdk/python/sport-client-joy.html">Sport Client Joystick (Python)</a></li><li><a href="/RBQ/nightly/software/sdk/cpp/sport-client.html">Sport Client (C++)</a></li><li><a href="/RBQ/nightly/software/sdk/python/overview.html">Python SDK Overview</a></li></ul>`,23)])])}const u=e(s,[["render",n]]);export{m as __pageData,u as default};
